unsafe fn c_strlen(s: *const c_char) -> usize {
    let mut n = 0isize;
    while *s.offset(n) != 0 {
        n += 1;
    }
    n as usize
}

unsafe fn c_strchr(s: *const c_char, c: c_char) -> *mut c_char {
    let mut p = s;
    loop {
        if *p == c {
            return p as *mut c_char;
        }
        if *p == 0 {
            return std::ptr::null_mut();
        }
        p = p.offset(1);
    }
}

unsafe fn c_strcmp(a: *const c_char, b: *const c_char) -> c_int {
    let mut i: isize = 0;
    loop {
        let ca = *a.offset(i);
        let cb = *b.offset(i);
        if ca != cb {
            return (ca as c_int) - (cb as c_int);
        }
        if ca == 0 {
            return 0;
        }
        i += 1;
    }
}

unsafe fn c_strcpy(dst: *mut c_char, src: *const c_char) {
    let mut i: isize = 0;
    loop {
        let c = *src.offset(i);
        *dst.offset(i) = c;
        if c == 0 {
            break;
        }
        i += 1;
    }
}

unsafe fn c_atoi(s: *const c_char) -> c_int {
    let cstr = std::ffi::CStr::from_ptr(s);
    let text = String::from_utf8_lossy(cstr.to_bytes());
    let trimmed = text.trim_start();
    let mut idx = 0usize;
    if let Some(c) = trimmed.chars().next() {
        if c == '+' || c == '-' {
            idx = c.len_utf8();
        }
    }
    let mut end = idx;
    for (i, c) in trimmed[idx..].char_indices() {
        if c.is_ascii_digit() {
            end = idx + i + c.len_utf8();
        } else {
            break;
        }
    }
    trimmed[..end].parse::<c_int>().unwrap_or(0)
}

